app.get("/animeData", async(req, res) => {
    try {
        const Anime = await AnimeData.find();
        res.json(Anime);
    } catch (err) {
        res.status(500).json({ error: "Error fetching movies" });
    }
});


const PORT = process.env.PORT || 8080;
app.listen(PORT, () => {
    console.log(`🚀 Server is running on port ${PORT}`);
});